node -e "
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');

// 1. Chunked: CRLF split across chunks
let p = createParser();
assert.deepEqual(p.push('a\r'), [['a']]);
assert.deepEqual(p.push('\nb'), []);
assert.deepEqual(p.end(), [['b']]);

// 2. CRLF inside quoted field across chunks: preserved, counted once
p = createParser();
assert.deepEqual(p.push('\"x\r'), []);
assert.deepEqual(p.push('\ny\"'), []);
assert.deepEqual(p.push(',z\n'), [['x\r\ny', 'z']]);

// 3. Escaped quote split across chunks
p = createParser();
assert.deepEqual(p.push('\"a\"'), []);
assert.deepEqual(p.push('\"b\"\n'), [['a\"b']]);

// 4. Surrogate pair split across chunks
p = createParser();
const s = '💩';
assert.deepEqual(p.push(s[0]), []);
assert.deepEqual(p.push(s[1] + '\n'), [[s]]);

// 5. BOM only at start; empty chunk before BOM ok
p = createParser();
assert.deepEqual(p.push(''), []);
assert.deepEqual(p.push('﻿a\n'), [['a']]);
assert.deepEqual(parse('a﻿b\n'), [['a﻿b']]); // later BOM is data
assert.deepEqual(parse('﻿'), []);
assert.deepEqual(parse(''), []);

// 6. Separators
assert.deepEqual(parse('\n'), [['']]);
assert.deepEqual(parse('\n\n'), [[''], ['']]);
assert.deepEqual(parse('a\n'), [['a']]);
assert.deepEqual(parse('a\r\rb\r\n'), [['a'], ['b']]);
assert.deepEqual(parse('a\r\n\nb'), [['a'], [''], ['b']]);

// 7. Error: junk after closing quote, with line number
assert.throws(() => parse('\"a\" x\n'), (e) => e instanceof SyntaxError && e.message.includes('line 1'));
assert.throws(() => parse('ok\n\"a\" \n'), (e) => e instanceof SyntaxError && e.message.includes('line 2'));
// line counts newlines inside quotes (CRLF once)
assert.throws(() => parse('\"a\r\nb\nc\" x'), (e) => e.message.includes('line 3'));

// 8. Unterminated quote at end, line at EOF
p = createParser();
p.push('\"a\nb');
assert.throws(() => p.end(), (e) => e instanceof SyntaxError && e.message.includes('line 2'));

// 9. Lifecycle
p = createParser();
p.push('a\n');
assert.deepEqual(p.end(), []);
assert.deepEqual(p.end(), []);
assert.throws(() => p.push(''), Error);
assert.throws(() => p.push('x'), Error);
assert.throws(() => createParser().push(42), TypeError);

// 10. Delimiter validation
assert.throws(() => createParser({ delimiter: '' }), RangeError);
assert.throws(() => createParser({ delimiter: ';;' }), RangeError);
assert.throws(() => createParser({ delimiter: '\"' }), RangeError);
assert.throws(() => createParser({ delimiter: '\n' }), RangeError);
assert.throws(() => createParser({ delimiter: '\r' }), RangeError);
assert.throws(() => createParser({ delimiter: 1 }), RangeError);
assert.deepEqual(parse('a;b\nc;d', { delimiter: ';' }), [['a','b'],['c','d']]);

// 11. Only newly completed records per push
p = createParser();
assert.deepEqual(p.push('a\nb\n'), [['a'], ['b']]);
assert.deepEqual(p.push('c'), []);
assert.deepEqual(p.push('\n'), [['c']]);
assert.deepEqual(p.end(), []);

// 12. end with trailing delimiter / quoted field at EOF
p = createParser();
assert.deepEqual(p.push('a,'), []);
assert.deepEqual(p.end(), [['a', '']]);
assert.deepEqual(parse('\"q\"'), [['q']]);
assert.deepEqual(parse('a,,b'), [['a', '', 'b']]);

// 13. header mode: duplicates, padding, proto key, empty
assert.deepEqual(parse('x,x\n1\n', { header: true }), [{ x: '1', x_2: '' }]);
assert.deepEqual(parse('', { header: true }), []);
assert.deepEqual(parse('h\n', { header: true }), []);
const r = parse('__proto__\nv\n', { header: true });
assert.equal(Object.getPrototypeOf(r[0]), Object.prototype);
assert.equal(Object.prototype.hasOwnProperty.call(r[0], '__proto__'), true);
assert.equal(r[0].__proto__, 'v');

// 14. Independent parsers
const p1 = createParser(), p2 = createParser();
p1.push('\"a');
p2.push('b\n');
assert.deepEqual(p2.end(), []);
assert.deepEqual(p1.push('\"\n'), [['a']]);

console.log('all contract checks passed');
"
